interface UserRecord {
  id: string;
  username: string;
  email: string;
  salt: string;
  passwordHash: string;
  keyVerification: string;
  createdAt: number;
}

interface EncryptedVaultRecord {
  userId: string;
  ciphertext: string;
  iv: string;
  version: number;
  updatedAt: number;
  clientTimestamp: number;
  lastDeviceId?: string;
  checksum?: string;
}

interface DeviceRecord {
  id: string;
  userId: string;
  name: string;
  type: 'mobile' | 'tablet' | 'desktop';
  os: string;
  browser: string;
  ip: string;
  lastActive: number;
  registeredAt: number;
}

